class AssessmentSystem:
    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        self.students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if name in self.students:
            self.students[name]['courses'][course] = score

    def get_gpa(self, name):
        if name in self.students and self.students[name]['courses']:
            return sum(self.students[name]['courses'].values()) / len(self.students[name]['courses'])
        return None

    def get_all_students_with_fail_course(self):
        return [name for name in self.students if any(score < 60 for score in self.students[name]['courses'].values())]

    def get_course_average(self, course):
        scores = [self.students[name]['courses'].get(course, None) for name in self.students]
        return sum(score for score in scores if score is not None) / len([score for score in scores if score is not None])

    def get_top_student(self):
        if self.students:
            return max(self.students, key=lambda name: self.get_gpa(name))
        return None
```

This code defines the `AssessmentSystem` class with methods to add students, add course scores, calculate GPA, find students with failing courses, get the average score of a specific course, and find the student with the highest GPA.

